INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(24499, 'plPL', 'Echa udręczonych dusz', 'Nie potrafię ci dość podziękować za przybycie. Mamy dramatycznie mało ludzi, by ryzykować wyprawę do cytadeli, ale takie okazje trafiają się zbyt rzadko, by je przepuścić.$B$BCzekam na przybycie czempionów z koloseum, ale jeśli twoja reputacja nie kłamie, powinno ci w zupełności wystarczyć sił, by przebić się przez kuźnię. Oczyść drogę na drugi koniec i zabezpiecz przejście do Czeluści Saronu. Musimy je utrzymać, by poprowadzić naszych ludzi dalej w głąb cytadeli.$B$BProszę, pospiesz się, $n. Liczymy na ciebie.', 'Zabij Bronjahma i Pożeracza dusz, by zapewnić dostęp do Czeluści Saronu.', '', 'Porozmawiaj z lady Jainą Proudmoore w tylnej części Kuźni Dusz.', '', '', '', '', 0),
(24511, 'plPL', 'Echa udręczonych dusz', 'Cieszę się, że mamy kogoś, kto potrafi nam w tym pomóc. Wyprawa w głąb cytadeli tak nielicznymi siłami to w najlepszym razie ryzyko, ale takie okazje trafiają się zbyt rzadko, by je przepuścić.$B$BCzekam na przybycie czempionów z koloseum, ale jeśli twoja reputacja nie kłamie, powinno ci w zupełności wystarczyć sił, by przebić się przez kuźnię. Oczyść drogę na drugi koniec i zabezpiecz przejście do Czeluści Saronu. Musimy je utrzymać, by poprowadzić naszych ludzi dalej w głąb cytadeli.$B$BPospiesz się, $n. Czasu jest mało.', 'Zabij Bronjahma i Pożeracza dusz, by zapewnić dostęp do Czeluści Saronu.', '', 'Porozmawiaj z lady Sylwaną Bieżywiatr w tylnej części Kuźni Dusz.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24499, 'plPL', 'W samą porę! Dziękuję, $N.$B$BPrzed nami Czeluść Saronu, a jeśli nasi zwiadowcy się nie mylą, za nią znajdują się Sale Odbić. To tam Arthas traci czujność i to tam liczymy na znalezienie wskazówki co do jego słabości... a może, tylko może, jego odkupienia.', 0),
(24511, 'plPL', 'W samą porę, $N!$B$BPrzed nami Czeluść Saronu, a jeśli nasi zwiadowcy się nie mylą, za nią znajdują się Sale Odbić. To tam Arthas traci czujność i to tam liczymy na znalezienie wskazówki co do jego słabości... i drogi do zemsty, na którą czekamy zbyt długo.', 0);
